                        "entities": [obj_id] if obj_id else [],
                        "value": None,
                        "src": [[child["node_id"], line_index]],
                    })
            break

    # Motion log
    for child in children(doc, scope_node):
        if child["kind"] == "table" and child["title"].startswith(f"{scope}: Motion log"):
            for row_index, row in table_rows(child):
                fr = float(row["frame"])
                obj_descr = row["object"]
                obj_id = obj_descr.split()[0]
                fields = {
                    "x": float(row["x"]),
                    "y": float(row["y"]),
                    "vx": float(row["vx"]),
                    "vy": float(row["vy"]),
                    "speed": float(row["speed"]),
                }
                outcomes_list.append({
                    "time": fr,
                    "kind": "motion",
                    "entities": [obj_id],
                    "value": fields,
                    "src": [[child["node_id"], row_index, ["frame", "object", "x", "y", "vx", "vy", "speed"]]],
                })
            break

    return outcomes_list


def params(doc, scope: str):
    """
    Return a dictionary of constant parameters if any are mentioned.
    CLEVRER video annotations contain no declared constants, so return an empty dict.
    """
    return {}


# ---- step 2: forward model ----
import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER video annotations.

    Rules inferred from the front‑matter:
    * All objects move with constant velocity between events.
    * Collision occurs when the Euclidean distance between two objects
      falls below a small constant (here 0.1 metres).  Violence vectors are
      swapped for an elastic collision.
    * An object exits the scene when its centre lies outside the square
      |x| <= 5 and |y| <= 5.
    * Motion is friction‑free; velocities are never modified except at
      collisions or explicit “enter” events.

    The simulation runs in a 0.1‑frame time step – fine enough to capture
    the recorded events without excessive computation.
    """
    COLLISION_DIST = 0.1   # metres – chosen from data analysis
    EXIT_LIMIT = 5.0       # scene boundary

    # ------------------------------------------------------------------
    # 1. Build the initial state from the supplied inputs only
    # ------------------------------------------------------------------
    state = {}          # id -> {"pos":(x,y), "vel":(vx,vy)}
    active = set()      # ids of objects currently in the scene

    for inp in inputs:
        obj_id = inp["entities"][0]
        if inp["kind"] == "init_state":
            f = inp["fields"]
            state[obj_id] = {"pos": (f["x"], f["y"]),
                             "vel": (f["vx"], f["vy"])}
            active.add(obj_id)
        elif inp["kind"] == "enter":
            if obj_id not in state:
                state[obj_id] = {"pos": (0.0, 0.0), "vel": (0.0, 0.0)}
            active.add(obj_id)

    # ------------------------------------------------------------------
    # 2. Determine simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = min(inp["time"] for inp in inputs) if inputs else 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    dt = 0.1  # timestep in frames

    # ------------------------------------------------------------------
    # 3. Helper utilities
    # ------------------------------------------------------------------
    def distance(p, q):
        return math.hypot(p[0] - q[0], p[1] - q[1])

    def make_outcome(time, kind, entities, value):
        return {
            "time": round(time, 6),
            "kind": kind,
            "entities": entities,
            "value": value,
            "src": None
        }

    # ------------------------------------------------------------------
    # 4. Simulation loop
    # ------------------------------------------------------------------
    outcomes = []
    t = start

    while t <= horizon + 1e-9:
        # Advance every active object
        for oid in list(active):
            p = state[oid]["pos"]
            v = state[oid]["vel"]
            state[oid]["pos"] = (p[0] + v[0] * dt, p[1] + v[1] * dt)

        # Emit motion at integer frame times
        if abs(t - round(t)) < dt / 2:
            for oid in active:
                pos = state[oid]["pos"]
                vel = state[oid]["vel"]
                outcomes.append(make_outcome(
                    t, "motion", [oid],
                    {"x": pos[0], "y": pos[1],
                     "vx": vel[0], "vy": vel[1],
                     "speed": math.hypot(*vel)}
                ))

        # Detect collisions
        checked = set()
        for oid1 in list(active):
            for oid2 in list(active):
                if oid1 >= oid2 or (oid1, oid2) in checked:
                    continue
                checked.add((oid1, oid2))
                if distance(state[oid1]["pos"], state[oid2]["pos"]) <= COLLISION_DIST:
                    outcomes.append(make_outcome(t, "collision", [oid1, oid2], None))
                    # Swap velocities for an elastic collision
                    state[oid1]["vel"], state[oid2]["vel"] = (
                        state[oid2]["vel"], state[oid1]["vel"]
                    )

        # Detect exits
        for oid in list(active):
            p = state[oid]["pos"]
            if abs(p[0]) > EXIT_LIMIT or abs(p[1]) > EXIT_LIMIT:
                outcomes.append(make_outcome(t, "exit", [oid], None))
                active.remove(oid)
                state.pop(oid)

        t += dt

    # ------------------------------------------------------------------
    # 5. Return outcomes occurring after the requested `start`
    # ------------------------------------------------------------------
    return [o for o in outcomes if o["time"] >= start]
